import java.io.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.text.StringSubstitutor;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Template cache for report generation
    private Map<String, String> templateCache = new HashMap<>();

    @Override
    public void init() throws ServletException {
        templateCache.put("sales", "SELECT order_id, customer_name, amount, region FROM orders WHERE region = '${region}' AND quarter = '${quarter}'");
        templateCache.put("inventory", "SELECT sku, warehouse, qty_on_hand FROM inventory WHERE warehouse_code = '${warehouse}' AND category = '${category}'");
        templateCache.put("custom", "SELECT ${columns} FROM ${table} WHERE ${filter}");
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {

        String reportType = req.getParameter("report_type");
        if (reportType == null || !templateCache.containsKey(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate session - only authenticated analysts can run reports
        HttpSession session = req.getSession(false);
        if (session == null || session.getAttribute("role") == null) {
            resp.sendError(401, "Authentication required");
            return;
        }

        String role = (String) session.getAttribute("role");
        if ("custom".equals(reportType) && !"admin".equals(role)) {
            resp.sendError(403, "Custom reports require admin role");
            return;
        }

        // Build parameter map from request
        Map<String, String> params = new HashMap<>();
        Enumeration<String> paramNames = req.getParameterNames();
        while (paramNames.hasMoreElements()) {
            String name = paramNames.nextElement();
            if (!"report_type".equals(name)) {
                String value = req.getParameter(name);
                // Basic sanitization - remove comments and semicolons
                value = value.replaceAll("--", "").replaceAll(";", "");
                // Block obvious UNION attacks
                if (value.toUpperCase().contains("UNION") && value.toUpperCase().contains("SELECT")) {
                    resp.sendError(400, "Invalid characters in parameter");
                    return;
                }
                params.put(name, value);
            }
        }

        // Interpolate template
        String template = templateCache.get(reportType);
        StringSubstitutor sub = new StringSubstitutor(params);
        String query = sub.replace(template);

        // Execute and return results
        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.print("  {");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) out.print(", ");
                    out.printf("\"%s\": \"%s\"", meta.getColumnName(i), 
                              rs.getString(i) != null ? rs.getString(i).replace("\"", "\\\"") : "null");
                }
                out.print("}");
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            resp.sendError(500, "Query execution error");
        }
    }
}
